"""Exact-scope independent review record; preserves all unassigned commentary."""
from pathlib import Path
from datetime import datetime,timezone
import json,re,hashlib,xml.etree.ElementTree as E,sys
W=Path(__file__).resolve().parent;D=W/'sources/review-p90-p105'
IDS='p90 p91 p91a p92 p93 p93a p94 p95 p95a p96 p96a p97 p98 p99 p100 p101 p102 p103 p104 p105'.split()
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
sht=lambda s:hashlib.sha256(s.encode()).hexdigest()
def save(p,o):p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
notes={
'p90':('retained','Alle vier Absätze gelesen. Billigkeit bei mehreren Beteiligten und Eigenkostengrundsatz von zwingender Last bei erfolgloser oder unzulässiger Rechtsbeschwerde und grob schuldhafter Kostenverursachung getrennt. Begrenzte Kostenlast der Amtsleitung sowie Festsetzungs-/Vollstreckungsverweisung stimmen. Beispiel zur unstatthaften Rechtsbeschwerde sachgerecht; keine automatische volle Erstattung beliebiger Privatauslagen behauptet.'),
'p91':('corrected','Alle acht Absätze geprüft. Fehlerhafte Gleichsetzung von Glaubhaftmachung und Nachholung innerhalb der Zweimonatsfrist beseitigt: Abs. 3 erlaubt Glaubhaftmachung auch im Antragsverfahren, Abs. 4 verlangt fristgerechte Nachholung. Gebundene Gewährung bei erfüllten Voraussetzungen, Widerspruchsausnahmen, Jahresgrenze, Zuständigkeit, Unanfechtbarkeit der Gewährung und begrenzter Zwischenbenutzerschutz präzisiert. Keine allgemeine Unanfechtbarkeit der Versagung oder dauerhafte Weiterbenutzungsbefugnis abgeleitet.'),
'p91a':('corrected','Alle vier Absätze und § 6 PatKostG gelesen. Amtlich bestimmte Frist, Zurückweisung gerade wegen Versäumung, Monatsbeginn ab Zustellung, Antrag, Nachholung und Gebührenzahlung getrennt. Verschuldensunabhängigkeit erläutert; Wiederaufnahme nicht mit Eintragung gleichgesetzt. Wiedereinsetzungsausschluss beider bezeichneten Fristen und Entscheidungskompetenz erhalten. Keine Anwendung auf gesetzliche Widerspruchs- oder Beschwerdefrist zugesagt.'),
'p92':('corrected','Gesamten Wortlaut und §§ 43, 53, 59, 73 gelesen. Wahrheit/Vollständigkeit tatsächlicher Angaben von Rechtsargumenten, unsicherer Erkenntnis und Beweislast getrennt. Vorherige missverständliche Wendung zu eidesstattlichen Versicherungen nach §§ 43/53 durch bedingten Beweisvorlagefall ersetzt; keine gesetzlich zwingende oder generell ausreichende Versicherung behauptet. Kein automatischer Markenverlust als Sanktion erfunden.'),
'p93':('corrected','Gesamte Norm, § 65 Abs. 1 Nr. 11, § 107 Abs. 2 und GVG §§ 184–187, 189 gelesen. Deutsch als Verfahrenssprache von Dokumentensprache und persönlicher Verständigung getrennt. Dolmetscher und barrierefreie Kommunikation konkretisiert, besondere Registrierungssprache eingegrenzt. Strafprozessuale kostenlose Übersetzung nicht pauschal in Registerverfahren übernommen.'),
'p93a':('retained','Gesamten Wortlaut geprüft. Entschädigung des Zeugen und Vergütung des Sachverständigen zutreffend dem JVEG zugeordnet. Kein ungeprüfter Stundensatz; privat bestellte Berichte nicht automatisch als gesetzlich vergütete gerichtliche Gutachten behandelt. Erstattung privater Aufwendungen von eigenem gesetzlichen Vergütungsanspruch getrennt.'),
'p94':('corrected','Beide Absätze, alle vier Nummern sowie ZPO § 184 und VwZG §§ 5, 7, 8 gelesen. Auslandspostregel einschließlich selbst als Vertreter auftretenden Empfängern, Zweiwochenfiktion und selektiver Satzverweis ergänzt. Erlaubnisscheininhaber/Empfangsbekenntnis, besondere Dreitagesregel des Abholfachs, elektronische Sicherheitsanforderungen und ZPO-Regime des BPatG getrennt. Heilung und Empfangsberechtigung ergänzen die Fristprüfung.'),
'p95':('retained','Alle drei Absätze und § 56 Abs. 2 gelesen. Gerichtliche Rechtshilfe, Ordnungs-/Zwangsmittel sowie Zeugenvorführung auf Ersuchen, Beschwerdesenat mit drei rechtskundigen Mitgliedern und Beschlussform vollständig. Berechtigte Weigerungsgründe ausdrücklich vorbehalten; keine Gleichsetzung des Ersuchens mit automatischer Sanktion. § 58 zutreffend als andere Unterstützungsrichtung abgegrenzt.'),
'p95a':('corrected','Alle drei Absätze und Nummern sowie aktuellen § 130a ZPO gelesen. Für das Amt nur Abs. 1, Abs. 2 Satz 1 und Abs. 5/6 übernommen; gerade keine pauschale Einbeziehung Abs. 3/4. Empfangsspeicherung, Bestätigung, beschränkte Formatheilung und Glaubhaftmachung der Inhaltsgleichheit entfaltet. Gerichtsakten und Amtsdokumente, Verordnungskompetenz sowie Eingang/Ausgang getrennt. Keine beliebige E-Mail oder ungeprüftes Format als zulässig erklärt.'),
'p96':('corrected','Alle drei Absätze und § 23 ZPO gelesen. Inlandsbezug statt Staatsangehörigkeit, Befugnis plus Vollmacht einschließlich Strafanträgen und bürgerlichen Streitigkeiten konkretisiert. Belegenheitsfiktion mit Geschäftsraum/Wohnsitz/DPMA-Ersatzfolge erklärt, kein allgemeiner Universalgerichtsstand behauptet. Beendigungs- und Nachfolgeranzeige von interner Kündigung getrennt; § 85-BGH-Anwaltszwang bleibt eigenständig.'),
'p96a':('corrected','Gesamte Verweisung und GVG §§ 198–201 gelesen. Gerichtliche Dauer von DPMA-Bearbeitung abgegrenzt; Einzelfallkriterien, Nachteil, Verzögerungsrüge, Wiederholung und Gerichtwechsel erklärt. Sechsmonatige Wartezeit zur Klage und sechsmonatige Schlussfrist ab Rechtskraft/Erledigung getrennt. Kein fixer automatischer Geldanspruch, keine Gleichsetzung von Sachstandsanfrage und Rüge oder mit § 89a; Checkliste entsprechend präzisiert.'),
'p97':('corrected','Beide Absätze gelesen. Verbandliche Zuordnung auch bei Qualitäts-/Geografiefunktion präzisiert; Anmeldebezeichnung, allgemeine Schutzfähigkeit und Sonderregeln getrennt. BPatG 24 W (pat) 33/09 volltextgeprüft: konkreter Slogan ohne kollektive Unterscheidungskraft, kein generelles Sloganverbot. Beispiel und Abgrenzung § 106a erhalten.'),
'p98':('retained','Gesamten Katalog einschließlich Dach-/Spitzenverbänden und gleichgestellten juristischen Personen öffentlichen Rechts gelesen. Besondere Rechte-/Pflichtenfähigkeit, Handlungs- und Prozessfähigkeit zutreffend erklärt; keine Vereinsregistereintragung oder einzige Rechtsform erfunden. Informeller Gesprächskreis mit persönlichem Sprecher als Inhaber genügt nicht allein wegen Kooperation; § 105/106b-Verweise passen.'),
'p99':('corrected','Beide Absätze und Art. 5 Nr. 14/15, Art. 16 BGBl. 2026 I Nr. 9 geprüft. Nur § 8 Abs. 2 Nr. 2 ausgenommen, andere Hindernisse und Aufnahmegebot bleiben. Umzug der geografischen Schranke von § 100 Abs. 1 nach § 99 Abs. 2 seit 16.01.2026 und entfallener ausdrücklicher § 127-Zusatz offengelegt. BGH I ZR 163/19 vollständig gelesen: Gesamtwürdigung, keine Unredlichkeit allein wegen Zeichenidentität; damalige EU-Verordnung nicht als heutiges Recht übernommen.'),
'p100':('corrected','Gesamten unnummerierten Satz sowie § 26 und Januaränderung gelesen. Mindestens ein befugter Nutzer oder Inhaber genügt; Ernsthaftigkeit, Waren-/Zeit-/Formbezug bleiben. Aktuelle Entnummerierung gegenüber altem Abs. 2 klargestellt; frühere geografische Schranke nicht als heutiger § 100 behandelt. Frühere zu pauschale Gleichsetzung jeder satzungswidrigen Verwendung mit Unbefugtheit durch konkrete Berechtigungsprüfung ersetzt.'),
'p101':('retained','Beide Absätze und § 102 Abs. 2 Nr. 6 gelesen. Dispositive Satzungsregel zur Zustimmung, eigenständige Klagebefugnis und gebündelter Ersatz für Nutzerschäden richtig getrennt. Keine automatische Klagebefugnis aus Mitgliedschaft, kein mehrfacher Ersatz desselben Schadens; Beispiel verlangt nachvollziehbare Zuordnung und Abstimmung paralleler Ansprüche.'),
'p102':('corrected','Alle fünf Absätze und sechs Mindestangaben geprüft. Mitgliedschaft, konkrete Nutzungsbefugnis, Benutzungsbedingungen und Rechtsverfolgung klarer getrennt. Aufnahmegebot bei Herkunft plus erfüllten Bedingungen, Registereintragung und freie Einsicht ohne Interessenbeleg präzisiert. BGH I ZR 163/19 Rn. 50 nur für Funktion der Qualitätsbedingungen, nicht als Billigung beliebiger Aufnahmebedingungen herangezogen.'),
'p103':('corrected','Alle drei Absätze und § 37 gelesen. Allgemeine Schutzfähigkeit, besondere Anforderungen §§ 97/98/102, ordnungs-/sittenwidrige Satzung und Irreführung über Markencharakter getrennt. Volltextbeleg Wasser bewegt uns konkret eingebunden. Satzungsänderung rettet nur tatsächlich beseitigte besondere Zurückweisungsgründe, nicht automatisch jedes allgemeine Schutzhindernis.'),
'p104':('retained','Alle vier Absätze und § 37 Abs. 6 Satz 2 gelesen. Mitteilung jeder Änderung, entsprechende §§ 102/103-Prüfung und konstitutive Registerwirkung für Markengesetz richtig. Drittbemerkung verschafft nicht automatisch Beteiligtenstellung; Beispiel trennt internen Beschluss und Eintragung. Überholte 2011-Aussage zur fehlenden Eintragbarkeit von Satzungsänderungen gerade nicht übernommen.'),
'p105':('retained','Alle drei Absätze und vier Verfallsgründe sowie §§ 49, 53, 103, 104 gelesen. Inhaberwegfall, fehlende Missbrauchsmaßnahmen, irreführende befugte Nutzung und rechtswidrige eingetragene Änderung unterschieden. Heilung nur im ausdrücklich bezeichneten Änderungsfall, keine pauschale Heilung sämtlicher Verstöße. Abs. 2 konkretisiert Missbrauch; Abs. 3 DPMA und § 53. Früheres Urteil mit damaliger Nr. 3 nicht unbesehen als heutige Nummerierung zitiert.')}
assert set(notes)==set(IDS)
def blocks():
 d={}
 for p in sorted((W/'commentary').glob('*.md')):
  for m in re.finditer(r'^=== (\S+)\n(.*?)(?=^=== |\Z)',p.read_text(),re.M|re.S):
   assert m[1] not in d;d[m[1]]=m[2].strip()
 return d
base=json.loads((D/'commentary-baseline.json').read_text());before=base['commentary'];current=blocks();assert set(current)==set(before)
changed=[i for i in current if current[i]!=before[i]];assert len(changed)==13 and set(changed)<=set(IDS)
assert all((i in changed)==(notes[i][0]=='corrected') for i in IDS)
us={u['id']:u for u in map(json.loads,(W/'units.jsonl').read_text().splitlines())}
r=E.parse(D/'markeng.xml').getroot();ns={n.attrib['doknr']:n for n in r.findall('norm')};compact=lambda s:re.sub(r'\s+','',s)
findings=[]
for i in IDS:
 u=us[i];n=ns[u['xml_doknr']];assert compact(u['text'])==compact(''.join(n.find('textdaten/text/Content').itertext()))
 findings.append(dict(id=i,label=u['label'],outcome=notes[i][0],finding=notes[i][1],resolved=True,source_xml_doknr=u['xml_doknr'],statutory_text_sha256=sht(u['text']),commentary_before_sha256=sht(before[i]),commentary_after_sha256=sht(current[i])))
cases=[]
for name,court,date,docket,scope,support,card,limit in [('wasser','BPatG','2010-10-26','24 W (pat) 33/09','Vollständiger Tenor und Gründe Rn. 1–26',['p97','p103'],'bpatg-wasser-bewegt-uns','Current collective distinctiveness under §§ 97/103 persists; modern § 103(2)/(3) explained from current statute, not retroactively attributed. No general slogan prohibition.'),('hohenlohe','BGH','2021-07-29','I ZR 163/19','Vollständiger Tenor, Tatbestand Rn. 1–5, Entscheidungsgründe Rn. 6–52, Namenszeilen',['p99','p102'],'bgh-hohenloher-landschwein','Former § 100(1) became § 99(2) on 16 January 2026; current anständige Gepflogenheiten expressly noted, prior express § 127 condition removed. Used only for bounded totality test/quality-function propositions, not continued application of former EU Regulation 1151/2012.')]:
 c=E.parse(D/(name+'.xml')).getroot();assert c.findtext('aktenzeichen')==docket;count=0;local=compact((D/(name+'-local.md')).read_text())
 for tag in ['tenor','tatbestand','entscheidungsgruende','gruende']:
  for e in c.findall('.//'+tag+'//p'):
   t=''.join(e.itertext()).strip()
   if t:assert compact(t) in local;count+=1
 cases.append(dict(court=court,date=date,docket=docket,ecli=c.findtext('ecli') or None,ecli_note='Official XML ECLI preserved; no inferred identifier',read_full_text=True,read_scope=scope,supported_reviewed_ids=support,official_xml='sources/review-p90-p105/'+name+'.xml',official_xml_sha256=sha(D/(name+'.xml')),corpus_path='sources/review-p90-p105/'+name+'-local.md',corpus_sha256=sha(D/(name+'-local.md')),nonempty_official_paragraphs_compared=count,missing_from_read_corpus=0,card='cases/'+card+'.md',superseded_law_check=limit))
now=datetime.now(timezone.utc).isoformat();prior=json.loads((D/'prior-review-result.json').read_text());assert prior['complete'] and set(prior['cumulative_reviewed_ids']).isdisjoint(IDS)
cumulative=list(dict.fromkeys(prior['cumulative_reviewed_ids']+IDS));assert len(cumulative)==120
coverage=json.loads((W/'completeness-independent.json').read_text());assert coverage['ok'];q=json.loads((W/'quality-report.json').read_text());assert not any(q[k] for k in ['broken_local_links','exact_repeated_paragraphs','repeated_long_sentences','placeholder_matches'])
limitations=['Completion applies only to exactly 20 assigned units p90–p105 including p91a, p93a, p95a and p96a. Previous 100 reviewed units preserved without renewed substantive review; 71 await second pass. No whole-book completion.', 'Selective case research: BPatG 24 W (pat) 33/09 and BGH I ZR 163/19 read in full in local corpus and compared to fresh official XML. Nine earlier case cards retained without renewed substantive review. No additional sufficiently specific case selected for remaining 16 assigned units; no assertion that none exists.', 'Official consolidation, both 2026 amending articles and actual commencement clauses checked; especially relocation of former § 100(1) to § 99(2) effective 16 January 2026. Selective later-amendment search is not an exhaustive BGBl legislative pipeline audit.', 'External individual-provision checks support concrete ZPO/GVG/VwZG/PatKostG references; no complete historical reconstruction or independent commentary of those acts, all regulations or every nested reference. No unverified fee amounts or universal technical filing formats introduced.', 'Firecrawl scrape failed for insufficient credits. Direct official HTTP fetches and official-domain web search supplied evidence instead; no successful Firecrawl extraction claimed for this batch.', 'Technical literal agreement, coverage, length, repetition and link checks do not prove legal errorlessness or external professional approval.']
validated='--validated' in sys.argv;technical=json.loads((W/'validation.json').read_text()) if validated else None
if validated:assert technical['ok'] and technical['verbatim_ratio']==1.0
result=dict(complete=validated,task='bounded_independent_second_pass',units_reviewed=20,reviewed_ids=IDS,decisive_date='2026-10-19',reviewed_at=now,unresolved_blockers=[],findings=findings,limitations=limitations,changed_ids=changed,retained_ids=[i for i in IDS if i not in changed],whole_book_complete=False,work_baseline_commit=base['work_baseline_commit'],baseline_evidence='sources/review-p90-p105/commentary-baseline.json',baseline_evidence_sha256=sha(D/'commentary-baseline.json'),unchanged_unassigned_units=171,unassigned_commentary_unchanged=True,prior_review_result='sources/review-p90-p105/prior-review-result.json',cumulative_reviewed_units=120,cumulative_reviewed_ids=cumulative,remaining_second_pass_units=71,case_checks=cases,source_preflight='preflight-result.json',source_verification='sources/verification.json',technical_validation=technical,technical_validation_pending=not validated,completeness=dict(expected=coverage['expected_count'],parsed=coverage['parsed_count'],missing=coverage['missing'],extra=coverage['unexpected'],xml_character_mismatch=coverage['xml_character_mismatch']),quality=dict(broken_links=q['broken_local_links'],repeated_long_sentences=q['repeated_long_sentences'],placeholder_matches=q['placeholder_matches']))
save(W/'review-result.json',result)
status=json.loads((W/'status.json').read_text());status.update(stage='bounded_second_pass_complete' if validated else 'bounded_second_pass_validation_pending',task_scope='Exactly p90–p105 including p91a, p93a, p95a and p96a; no whole-book completion.',reviewed_ids=IDS,units_reviewed=20,review_result='review-result.json',review_completed_at=now if validated else None,whole_book_review_complete=False,independent_second_pass='Current assigned 20 reviewed; 120 cumulatively reviewed, 71 pending',updated_at=now,remaining_limitations=limitations,unresolved_blockers=[],cumulative_reviewed_ids=cumulative,cumulative_reviewed_units=120,remaining_second_pass_units=71,commentary_characters=sum(map(len,current.values())))
verification=json.loads((W/'sources/verification.json').read_text());fetches=json.loads((D/'fetches.json').read_text())
for f in fetches:
 assert sha(W/f['path'])==f['sha256']
 if f['path'] not in {x['path'] for x in verification['fetches']}:verification['fetches'].append(f)
verification['bounded_review_p90_p105']['case_checks']=cases;verification['last_verified_at']=now;save(W/'sources/verification.json',verification)
status['source_checks']['latest_verification']=now
status['case_law_sources']=[x for x in status['case_law_sources'] if x['docket'] not in [c['docket'] for c in cases]]+[{k:c[k] for k in ['court','date','docket','card','read_full_text']} for c in cases]
status['case_law_provenance']='Two cases fully read and freshly verified in this batch; nine previous case cards retained without renewed substantive review.'
status['quality_checks'].update(output_local_links=q['checked_output_links'],broken_links=q['broken_local_links'],repeated_paragraphs=q['exact_repeated_paragraphs'],repeated_long_sentences=q['repeated_long_sentences'],other_commentary_blocks='All 171 unassigned commentary blocks unchanged against baseline '+base['work_baseline_commit'],unchanged_commentary_units=178,retained_reviewed_units=7,corrected_reviewed_units=13)
if validated:status['validation_result']=technical
save(W/'status.json',status)
support=set().union(*(set(c['supported_reviewed_ids']) for c in cases))
search=dict(checked_at=now,queries=[dict(query='site:rechtsprechung-im-internet.de Kollektivmarke § 100 ernsthafte Benutzung; site:rechtsprechung-im-internet.de MarkenG Wiedereinsetzung § 91',result='No useful official decision result returned in initial three-query web batch; no web snippet used as holding.'),dict(query='site:rechtsprechung-im-internet.de Kollektivmarke Unterscheidungskraft; site:recht.bund.de Markengesetz 2026 Änderung',evidence='sources/review-p90-p105/web-search.json',result='Selective official-domain search; no evidenced subsequent MarkenG amendment identified, no exhaustive legislative audit.')],local_corpus_queries=['rg -l Kollektivmarke /Volumes/LaCie/law-intake/eu/de/rii','rg -l --glob *.md § 91.*MarkenG|MarkenG.*§ 91 /Volumes/LaCie/law-intake/eu/de/rii'],candidate_inventory='sources/review-p90-p105/collective-candidates.txt',selected_cases=cases,excluded_candidate=dict(docket='27 W (pat) 111/10',date='2011-06-28',corpus='/Volumes/LaCie/law-intake/eu/de/rii/rii-mpre190480964.md',read='Tenor and grounds Rn. 1–66',reason='Historical VERO CUOIO discussion in Rn. 41–50 says statutory amendments to regulations were no longer registered then; current § 104(3) expressly makes registration constitutive, and former § 105(1) no. 3 is now no. 4. Not cited as current authority.'),fresh_fetches='sources/review-p90-p105/fetches.json',no_new_case_selected_ids=[i for i in IDS if i not in support],limit=limitations[1])
save(D/'search-log.json',search);log=json.loads((W/'sources/search-log.json').read_text());log['bounded_review_p90_p105']=search;save(W/'sources/search-log.json',log)
save(D/'firecrawl-attempt.json',dict(recorded_at=now,command="firecrawl scrape 'https://www.gesetze-im-internet.de/markeng/' -o sources/review-p90-p105-index-firecrawl.md",exit_code=1,result='Error: Insufficient credits to perform this request.',fallback='Direct official HTTP body capture and official-domain web search',successful_extraction=False))
preflight=json.loads((W/'preflight-result.json').read_text());preflight['verified_at']=now;preflight['task']='source_preflight_with_bounded_review_rechecks';save(W/'preflight-result.json',preflight)
manifest=dict(created_at=now,primary_statute='markeng.xml',canonical_statute='canonical.md',files=[dict(path=str(p.relative_to(W)),bytes=p.stat().st_size,sha256=sha(p)) for p in sorted((W/'sources').rglob('*')) if p.is_file() and p.name!='manifest.json']);save(W/'sources/manifest.json',manifest)
print(json.dumps(dict(complete=validated,reviewed=len(IDS),changed=len(changed),retained=20-len(changed),unchanged_unassigned=171,cumulative=120,remaining=71,official_case_paragraphs=sum(c['nonempty_official_paragraphs_compared'] for c in cases)),ensure_ascii=False))
